      "reason": "La page 5 autorise explicitement cette location immobilière, incluse parmi les actes fonciers, mais ne constate aucune adoption de règlement, d’où l’étape « inconnu »."
    },
    {
      "item": "i02",
      "choice": "v1",
      "reason": "La résolution 106-05-2026, page 6, fixe la consultation sur le projet de règlement 079-2026 au 13 juillet 2026 à 18 h 30, sans constater sa tenue ni l’adoption du règlement."
    },
    {
      "item": "i03",
      "choice": "absent",
      "reason": "L’intitulé cité page 6 ne constitue pas une unité distincte de la demande de suspension et de révision formulée page 8 et retenue en i06."
    },
    {
      "item": "i04",
      "choice": "v1",
      "reason": "La page 8 constate expressément le dépôt de l’avis spécial relatif à l’abrogation du règlement 046-2023, sans le présenter comme un avis de motion ou une adoption."
    },
    {
      "item": "i05",
      "choice": "absent",
      "reason": "Cette autorisation de location est le même acte foncier que celui retenu en i01, et la règle exclut le crédit d’un doublon du même fait."
    },
    {
      "item": "i06",
      "choice": "v1",
      "reason": "La résolution 107-05-2026 demande expressément, page 8, de suspendre et de réviser le projet de règlement sur les pratiques agroenvironnementales, sans constater sa suspension effective ni son adoption."
    },
    {
      "item": "i07",
      "choice": "absent",
      "reason": "Cette proposition répète l’autorisation de location déjà retenue en i01 et ne correspond donc pas à une unité gold distincte."
    },
    {
      "item": "i08",
      "choice": "absent",
      "reason": "Cette proposition reproduit la même demande, la même étape et la même citation que l’unité retenue en i06, constituant un doublon non crédité."
    }
  ]
